.hero__word {
  display: inline-block;
  color: var(--color-white);
  /* Reveal animation — fires on DOMContentLoaded; fill-mode: both keeps the
     element hidden (opacity 0) before the delay elapses, then holds the
     final state (opacity 1) after the animation completes. */
  animation: heroReveal 1200ms var(--ease-out) both;
  animation-delay: var(--delay, 0ms);
}

/* Hero reveal keyframes */
@keyframes heroReveal {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.hero__role {
  font-family: var(--font-heading);
  font-size: clamp(1.25rem, 3vw, 2rem);
  font-weight: 400;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-gold);
  margin-bottom: var(--space-md);
  /* Reveal animation — delay comes from inline --delay custom property (300ms) */
  animation: heroReveal 1200ms var(--ease-out) both;
  animation-delay: var(--delay, 0ms);
}

.hero__decorations {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

/* Individual SVG decoration layers — each is absolutely positioned within
   the hero__decorations container so they layer independently. */
.hero__deco {
  position: absolute;
  pointer-events: none;
}

/* Diagonal slash lines — right side, vertically centered */
.hero__deco--lines {
  right: clamp(2rem, 8vw, 8rem);
  top: 50%;
  transform: translateY(-50%);
  width: clamp(80px, 10vw, 160px);
  height: auto;
  opacity: 0.6;
}

/* Offset rectangles — top-right corner area */
.hero__deco--rects {
  right: clamp(0.5rem, 3vw, 4rem);
  top: clamp(4rem, 12vh, 8rem);
  width: clamp(70px, 9vw, 140px);
  height: auto;
  opacity: 0.7;
}

/* Diamond / rhombus shapes — bottom-right quadrant */
.hero__deco--diamonds {
  right: clamp(4rem, 14vw, 16rem);
  bottom: clamp(4rem, 12vh, 8rem);
  width: clamp(60px, 8vw, 110px);
  height: auto;
  opacity: 0.8;
}

/* Corner bracket accent — bottom-right corner */
.hero__deco--bracket {
  right: clamp(1rem, 4vw, 5rem);
  bottom: clamp(5rem, 14vh, 10rem);
  width: clamp(40px, 5vw, 70px);
  height: auto;
  opacity: 0.9;
}
